'use client';
const require_suggestion = require("./suggestion.cjs");
const require_suggestion_clear = require("./suggestion-clear.cjs");
const require_suggestion_empty = require("./suggestion-empty.cjs");
const require_suggestion_input = require("./suggestion-input.cjs");
const require_suggestion_list = require("./suggestion-list.cjs");
const require_suggestion_option = require("./suggestion-option.cjs");
const require_suggestion_toggle = require("./suggestion-toggle.cjs");
//#region src/components/suggestion/index.ts
/**
* A component that provides a suggestion list for an input field.
*
* @example
* <Suggestion>
*   <Suggestion.Input />
*   <Suggestion.Toggle />
*   <Suggestion.Clear />
*   <Suggestion.List>
*     <Suggestion.Empty>Tomt</Suggestion.Empty>
*     <Suggestion.Option value='Option 1'>Option 1</Suggestion.Option>
*     <Suggestion.Option value='Option 2'>Option 2</Suggestion.Option>
*   </Suggestion.List>
* </Suggestion>
*/
const EXPERIMENTAL_Suggestion = Object.assign(require_suggestion.Suggestion, {
	List: require_suggestion_list.SuggestionList,
	Input: require_suggestion_input.SuggestionInput,
	Empty: require_suggestion_empty.SuggestionEmpty,
	Option: require_suggestion_option.SuggestionOption,
	Toggle: require_suggestion_toggle.SuggestionToggle,
	Clear: require_suggestion_clear.SuggestionClear
});
EXPERIMENTAL_Suggestion.displayName = "EXPERIMENTAL_Suggestion";
EXPERIMENTAL_Suggestion.List.displayName = "EXPERIMENTAL_Suggestion.List";
EXPERIMENTAL_Suggestion.Input.displayName = "EXPERIMENTAL_Suggestion.Input";
EXPERIMENTAL_Suggestion.Empty.displayName = "EXPERIMENTAL_Suggestion.Empty";
EXPERIMENTAL_Suggestion.Option.displayName = "EXPERIMENTAL_Suggestion.Option";
EXPERIMENTAL_Suggestion.Toggle.displayName = "EXPERIMENTAL_Suggestion.Toggle";
EXPERIMENTAL_Suggestion.Clear.displayName = "EXPERIMENTAL_Suggestion.Clear";
//#endregion
exports.EXPERIMENTAL_Suggestion = EXPERIMENTAL_Suggestion;
exports.EXPERIMENTAL_SuggestionClear = require_suggestion_clear.SuggestionClear;
exports.EXPERIMENTAL_SuggestionEmpty = require_suggestion_empty.SuggestionEmpty;
exports.EXPERIMENTAL_SuggestionInput = require_suggestion_input.SuggestionInput;
exports.EXPERIMENTAL_SuggestionList = require_suggestion_list.SuggestionList;
exports.EXPERIMENTAL_SuggestionOption = require_suggestion_option.SuggestionOption;
exports.EXPERIMENTAL_SuggestionToggle = require_suggestion_toggle.SuggestionToggle;
